"""Inspect reviewed candidate-recall gaps without new model generation."""
import pathlib,json,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[3];RUN=ROOT/'benchmarks/runs/rewrite-history-chain-v1/run'
TARGETS={'history-0091':'Kubernetes','history-0124':'Prometheus','history-0143':'Grafana','history-0156':'Terraform','history-0161':'会议纪要','history-0188':'会议纪要','history-0211':'验收报告'}
def collect():
 rows=[json.loads(x) for x in (RUN/'results.jsonl').read_text().splitlines()];finals={r['id']:r for r in rows if r['stage']=='format'};selected={r['id']:r for r in rows if r['stage']=='selection'};readings=json.loads((ROOT/'benchmarks/artifacts/pypinyin-character-readings-v1/readings.json').read_text());records=[]
 for sid,target in TARGETS.items():
  r=finals[sid];hypotheses=r['prepared']['hypotheses'];candidates=[s for h in hypotheses for s in h['candidateSpellings']]
  records.append(dict(id=sid,reviewedTarget=target,source=r['source'],context=r['context'],rowSha256=hashlib.sha256(json.dumps(r,ensure_ascii=False,sort_keys=True).encode()).hexdigest(),targetInScreen=target in r['context'].get('Screen',''),proposed=target in candidates,modelSelectorCalled=sid in selected,actualDecision=selected[sid]['selection'] if sid in selected else None,finalBody=r['renderedBody']))
 return dict(kind='post-review-producer-coverage-diagnostic',newGenerations=0,resultsSha256=hashlib.sha256((RUN/'results.jsonl').read_bytes()).hexdigest(),records=records,toneExample=dict(sourceCharacter='受',sourceReadings=readings['受'],screenCharacter='收',screenReadings=readings['收'],exactReadingIntersection=sorted(set(readings['受'])&set(readings['收'])),sameSegmentIgnoringTone=bool({x.rstrip('12345') for x in readings['受']}&{x.rstrip('12345') for x in readings['收']})),scope='Human-selected normalization opportunities are evaluator-only, not a universal recall estimate or required phonetic ground truth. Chinese aliases may preserve meaning without canonical Latin spelling. Four cross-script targets and one different-tone word lack hypotheses; two exact-reading Chinese terms reach selection but are kept. Text-derived pronunciation is not acoustic evidence.')
if __name__=='__main__':print(json.dumps(collect(),ensure_ascii=False,indent=2))
